//! Parity of the daemon logic (scheduler, alerts/toasts, tray state) with fixtures generated by running the real
//! Python `app.App` in a sandbox (tools/gen_fixtures_daemon.py -> tests/fixtures/daemon.json).
//!
//! Every step replays the same ops with the same fake clock / random sequence / scripted fetch results and
//! compares the ordered side effects ("events") and the observable state afterwards.

use cu_core::cache::build_cache;
use cu_core::config::{Config, Profile};
use cu_core::daemon::{Env, FetchResult, Poller, TickInput, Toast, TrayView};
use serde_json::{json, Map, Value};
use std::cell::RefCell;
use std::collections::VecDeque;
use std::fs;
use std::path::PathBuf;
use std::rc::Rc;

struct Scripted {
    name: String,
    res: Value,
    advance: f64,
}

struct Shared {
    t: f64,
    rand: Vec<f64>,
    rand_used: usize,
    fq: VecDeque<Scripted>,
    rq: VecDeque<Scripted>,
    default_fetch: Value,
    ev: Vec<Value>,
}

#[derive(Clone)]
struct Fake(Rc<RefCell<Shared>>);

fn as_result(v: Value) -> Option<FetchResult> {
    match v {
        Value::Object(m) => Some(m),
        _ => None,
    }
}

impl Env for Fake {
    fn now(&self) -> f64 {
        self.0.borrow().t
    }
    fn rand(&mut self) -> f64 {
        let mut s = self.0.borrow_mut();
        let v = s.rand[s.rand_used % s.rand.len()];
        s.rand_used += 1;
        v
    }
    fn refresh_if_expired(&mut self, p: &Profile) -> Option<FetchResult> {
        let mut s = self.0.borrow_mut();
        s.ev.push(json!(["refresh", p.name]));
        if let Some(e) = s.rq.pop_front_if(|e| e.name == p.name) {
            s.t += e.advance;
            return as_result(e.res);
        }
        None
    }
    fn fetch(&mut self, p: &Profile) -> FetchResult {
        let mut s = self.0.borrow_mut();
        s.ev.push(json!(["fetch", p.name]));
        if let Some(e) = s.fq.pop_front_if(|e| e.name == p.name) {
            s.t += e.advance;
            return as_result(e.res).expect("scripted fetch result must be an object");
        }
        as_result(s.default_fetch.clone())
            .unwrap_or_else(|| panic!("unscripted fetch for {}", p.name))
    }
    fn write_cache(
        &mut self,
        cfg: &Config,
        data: &Map<String, Value>,
        busy: &[String],
        refresh: Option<Value>,
    ) {
        let mut out = build_cache(cfg, data, busy, refresh, 0.0);
        out.shift_remove("ts");
        self.0
            .borrow_mut()
            .ev
            .push(json!(["write", Value::Object(out)]));
    }
    fn refresh_icon(&mut self, v: &TrayView) {
        self.0.borrow_mut().ev.push(json!([
            "icon",
            v.tooltip,
            v.pct,
            v.color,
            v.text,
            v.bar_right,
            v.busy
        ]));
    }
    fn log(&mut self, msg: &str) {
        self.0.borrow_mut().ev.push(json!(["log", msg]));
    }
    fn save_alert_state(&mut self, st: &Map<String, Value>) {
        self.0
            .borrow_mut()
            .ev
            .push(json!(["alerts_save", Value::Object(st.clone())]));
    }
    fn send_toast(&mut self, t: &Toast) -> Result<(), String> {
        self.0
            .borrow_mut()
            .ev
            .push(json!(["toast", t.title, t.body]));
        Ok(())
    }
}

fn close(a: f64, b: f64) -> bool {
    a == b || (a - b).abs() <= 1e-6_f64.max(1e-12 * a.abs().max(b.abs()))
}

/// Semantic JSON equality (5 == 5.0). Object key order matters.
fn json_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => close(
            x.as_f64().unwrap_or(f64::NAN),
            y.as_f64().unwrap_or(f64::NAN),
        ),
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(p, q)| json_eq(p, q))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .zip(y.iter())
                    .all(|((k1, v1), (k2, v2))| k1 == k2 && json_eq(v1, v2))
        }
        _ => a == b,
    }
}

/// Like `json_eq` but object key order is ignored (maps whose order is not part of the contract).
fn json_eq_unordered(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(k, v)| y.get(k).is_some_and(|w| json_eq_unordered(v, w)))
        }
        _ => json_eq(a, b),
    }
}

fn load() -> Vec<Value> {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("daemon.json");
    let text = fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
    match serde_json::from_str(&text).expect("fixture JSON") {
        Value::Array(a) => a,
        _ => panic!("fixture is not a list"),
    }
}

fn obj(v: &Value) -> Map<String, Value> {
    v.as_object().cloned().unwrap_or_default()
}

fn scripted(v: Option<&Value>) -> VecDeque<Scripted> {
    v.and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .map(|e| Scripted {
                    name: e["name"].as_str().unwrap().to_string(),
                    res: e["res"].clone(),
                    advance: e.get("advance").and_then(Value::as_f64).unwrap_or(0.0),
                })
                .collect()
        })
        .unwrap_or_default()
}

fn observe(p: &Poller<Fake>, sh: &Shared) -> Value {
    let pending: Vec<Value> = p
        .pending
        .iter()
        .map(|q| json!({"t": q.t, "lvl": q.lvl, "name": q.name, "label": q.label, "v": q.v}))
        .collect();
    let sorted = |m: &std::collections::HashMap<String, f64>| {
        let mut e: Vec<_> = m.iter().collect();
        e.sort_by(|a, b| a.0.cmp(b.0));
        Value::Object(e.into_iter().map(|(k, v)| (k.clone(), json!(v))).collect())
    };
    let fails = {
        let mut e: Vec<_> = p.fails.iter().collect();
        e.sort_by(|a, b| a.0.cmp(b.0));
        Value::Object(e.into_iter().map(|(k, v)| (k.clone(), json!(v))).collect())
    };
    json!({
        "now": sh.t,
        "rand_used": sh.rand_used,
        "data": Value::Object(p.data.clone()),
        "next_at": sorted(&p.next_at),
        "fails": fails,
        "busy": p.busy.iter().collect::<Vec<_>>(),
        "refresh_info": p.refresh_info.clone().unwrap_or(Value::Null),
        "pending": pending,
        "last_toast": p.last_toast,
        "baseline": p.baseline,
        "alert_state": Value::Object(p.alert_state.clone()),
    })
}

fn diff_state(exp: &Value, got: &Value) -> Option<String> {
    for k in exp.as_object().unwrap().keys() {
        let (e, g) = (&exp[k], &got[k]);
        let same = if matches!(k.as_str(), "next_at" | "fails" | "data" | "alert_state") {
            json_eq_unordered(e, g)
        } else {
            json_eq(e, g)
        };
        if !same {
            return Some(format!("state.{k}: expected {e}\n     got {g}"));
        }
    }
    None
}

#[test]
fn daemon_parity() {
    let scenarios = load();
    assert!(scenarios.len() >= 50, "fixture looks truncated");
    let mut steps_run = 0;
    let mut failures: Vec<String> = Vec::new();
    for sc in &scenarios {
        let name = sc["name"].as_str().unwrap();
        let shared = Rc::new(RefCell::new(Shared {
            t: sc["t0"].as_f64().unwrap(),
            rand: sc["rand"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_f64().unwrap())
                .collect(),
            rand_used: 0,
            fq: VecDeque::new(),
            rq: VecDeque::new(),
            default_fetch: sc["default_fetch"].clone(),
            ev: Vec::new(),
        }));
        let alerts = if sc["alerts"].is_null() {
            None
        } else {
            Some(obj(&sc["alerts"]))
        };
        let mut p = Poller::new(Fake(shared.clone()), obj(&sc["cfg"]), alerts);
        for (i, st) in sc["steps"].as_array().unwrap().iter().enumerate() {
            {
                let mut s = shared.borrow_mut();
                s.t += st.get("dt").and_then(Value::as_f64).unwrap_or(0.0);
                s.ev.clear();
                let (f, r) = (scripted(st.get("fetch")), scripted(st.get("refresh")));
                s.fq.extend(f);
                s.rq.extend(r);
            }
            let op = st["op"].as_str().unwrap();
            match op {
                "start" => p.start(st.get("cache").filter(|c| !c.is_null())),
                "tick" => p.tick(TickInput {
                    config: st.get("config").filter(|c| c.is_object()).map(obj),
                    test_toast: st.get("flag_test").is_some_and(|v| v == true),
                    refresh: st.get("flag_refresh").is_some_and(|v| v == true),
                }),
                "refresh" => p.refresh_requested(),
                "test_toast" => p.test_toast(),
                "flush" => p.flush_toasts(),
                "publish" => p.publish(),
                "set_data" => p.data = obj(&st["data"]),
                other => panic!("unknown op {other}"),
            }
            steps_run += 1;
            let sh = shared.borrow();
            let got_ev = Value::Array(sh.ev.clone());
            let ctx = format!("{name} step {i} ({op})");
            if !json_eq(&st["events"], &got_ev) {
                failures.push(format!(
                    "{ctx}: events differ\n  expected {}\n       got {}",
                    st["events"], got_ev
                ));
                break;
            }
            if let Some(d) = diff_state(&st["state"], &observe(&p, &sh)) {
                failures.push(format!("{ctx}: {d}"));
                break;
            }
        }
        let sh = shared.borrow();
        if (failures.is_empty() || !failures.last().unwrap().starts_with(name))
            && (!sh.fq.is_empty() || !sh.rq.is_empty())
        {
            failures.push(format!("{name}: unused scripted results"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} scenarios failed ({steps_run} steps run):\n{}",
        failures.len(),
        scenarios.len(),
        failures.join("\n\n")
    );
}
